#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void sum_reduction_kernel(const float* input, float* output, int total_elements, int dim_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum_val = 0.0f;
        for (int i = 0; i < dim_size; ++i) {
            // Assuming input is stored with stride `dim_size` in the reduced dimension.
            int base_idx = idx * dim_size + i;
            sum_val += input[base_idx];
        }
        output[idx] = sum_val;
    }
}

torch::Tensor sum_reduction_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    if (x.dim() < 2 or dim >= x.ndim):
        return torch.zeros_like(x)

    // Allocate output tensor with same data type and shape as input,
